const listTeamChallengeAttemptLimits = `-- name: ListTeamChallengeAttemptLimits :many
SELECT tc.id AS team_challenge_id,
       COALESCE(ec.max_flag_attempts, cfg.max_flag_attempts) AS max_attempts,
       s.wrong::bigint AS wrong,
       s.solved::bool AS solved
FROM team_challenges tc
JOIN event_challenges ec ON ec.id = tc.event_challenge_id
LEFT JOIN event_configs cfg ON cfg.event_id = tc.event_id
CROSS JOIN LATERAL (
    SELECT count(*) FILTER (WHERE NOT x.effective_correct AND (x.first_correct IS NULL OR x.received_at < x.first_correct)) AS wrong,
           COALESCE(bool_or(x.first_correct IS NOT NULL), false) AS solved
    FROM (SELECT a.effective_correct, a.received_at,
                 min(a.received_at) FILTER (WHERE a.effective_correct) OVER () AS first_correct
          FROM effective_challenge_attempts a
          WHERE a.team_challenge_id = tc.id) x
) s
WHERE tc.event_team_id = $1
  AND COALESCE(ec.max_flag_attempts, cfg.max_flag_attempts) IS NOT NULL
`

type ListTeamChallengeAttemptLimitsRow struct {
	TeamChallengeID uuid.UUID   `json:"team_challenge_id"`
	MaxAttempts     pgtype.Int4 `json:"max_attempts"`
	Wrong           int64       `json:"wrong"`
	Solved          bool        `json:"solved"`
}

// GetTeamChallengeAttemptLimit for every limited team challenge of one team (the participant board).
func (q *Queries) ListTeamChallengeAttemptLimits(ctx context.Context, eventTeamID uuid.UUID) ([]ListTeamChallengeAttemptLimitsRow, error) {
	rows, err := q.db.Query(ctx, listTeamChallengeAttemptLimits, eventTeamID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTeamChallengeAttemptLimitsRow{}
	for rows.Next() {
		var i ListTeamChallengeAttemptLimitsRow
		if err := rows.Scan(
			&i.TeamChallengeID,
			&i.MaxAttempts,
			&i.Wrong,
			&i.Solved,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listTeamResultAttempts = `-- name: ListTeamResultAttempts :many
SELECT ca.id,
       ca.event_team_id,
       ca.user_id,
       event_participant_public_name(ca.event_id, ca.user_id)::text AS participant_name,
       ca.team_challenge_id,
       ec.id AS event_challenge_id,
       ca.answer,
       ca.automatic_correct,
       ca.effective_correct AS correct,
       ca.decision,
       ca.decision_reason,
       ca.decided_by,
       ca.decided_at,
       ca.received_at,
       ca.practice
FROM effective_challenge_attempts_all ca
JOIN users u ON u.id = ca.user_id
JOIN team_challenges tc ON tc.id = ca.team_challenge_id
JOIN event_challenges ec ON ec.id = tc.event_challenge_id
WHERE ca.event_id = $1
  AND ca.event_team_id = $2
ORDER BY ca.received_at DESC, ca.id DESC
`

type ListTeamResultAttemptsParams struct {
	EventID     uuid.UUID `json:"event_id"`
	EventTeamID uuid.UUID `json:"event_team_id"`
}

type ListTeamResultAttemptsRow struct {
	ID               uuid.UUID `json:"id"`
	EventTeamID      uuid.UUID `json:"event_team_id"`
	UserID           uuid.UUID `json:"user_id"`
	ParticipantName  string    `json:"participant_name"`
	TeamChallengeID  uuid.UUID `json:"team_challenge_id"`
	EventChallengeID uuid.UUID `json:"event_challenge_id"`
	Answer           string    `json:"answer"`
	AutomaticCorrect bool      `json:"automatic_correct"`
	Correct          bool      `json:"correct"`
	Decision         int16     `json:"decision"`
	DecisionReason   string    `json:"decision_reason"`
	DecidedBy        uuid.UUID `json:"decided_by"`
	DecidedAt        time.Time `json:"decided_at"`
	ReceivedAt       time.Time `json:"received_at"`
	Practice         bool      `json:"practice"`
}

func (q *Queries) ListTeamResultAttempts(ctx context.Context, arg ListTeamResultAttemptsParams) ([]ListTeamResultAttemptsRow, error) {
	rows, err := q.db.Query(ctx, listTeamResultAttempts, arg.EventID, arg.EventTeamID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTeamResultAttemptsRow{}
	for rows.Next() {
		var i ListTeamResultAttemptsRow
		if err := rows.Scan(
			&i.ID,
			&i.EventTeamID,
			&i.UserID,
			&i.ParticipantName,
			&i.TeamChallengeID,
			&i.EventChallengeID,
			&i.Answer,
			&i.AutomaticCorrect,
			&i.Correct,
			&i.Decision,
			&i.DecisionReason,
			&i.DecidedBy,
			&i.DecidedAt,
			&i.ReceivedAt,
			&i.Practice,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockEventTeamChallenge = `-- name: LockEventTeamChallenge :one
SELECT tc.id
FROM team_challenges tc
WHERE tc.event_id = $1
  AND tc.event_team_id = $2
  AND tc.event_challenge_id = $3
FOR UPDATE
`

type LockEventTeamChallengeParams struct {
	EventID          uuid.UUID `json:"event_id"`
	EventTeamID      uuid.UUID `json:"event_team_id"`
	EventChallengeID uuid.UUID `json:"event_challenge_id"`
}

// Locks one team challenge so an annulment serializes with submission-time
// scoring and single decisions (they lock the same row).
func (q *Queries) LockEventTeamChallenge(ctx context.Context, arg LockEventTeamChallengeParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockEventTeamChallenge, arg.EventID, arg.EventTeamID, arg.EventChallengeID)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const upsertTeamChallengePracticeSolve = `-- name: UpsertTeamChallengePracticeSolve :exec
INSERT INTO team_challenge_practice_solves (team_challenge_id, solved_at)
VALUES ($1, $2)
ON CONFLICT (team_challenge_id) DO NOTHING
`

type UpsertTeamChallengePracticeSolveParams struct {
	TeamChallengeID uuid.UUID `json:"team_challenge_id"`
	SolvedAt        time.Time `json:"solved_at"`
}

// A correct answer after a returnable stage closed: shown to the team, never rated.
func (q *Queries) UpsertTeamChallengePracticeSolve(ctx context.Context, arg UpsertTeamChallengePracticeSolveParams) error {
	_, err := q.db.Exec(ctx, upsertTeamChallengePracticeSolve, arg.TeamChallengeID, arg.SolvedAt)
	return err
}

const upsertTeamChallengeSolve = `-- name: UpsertTeamChallengeSolve :exec
INSERT INTO team_challenge_solves (team_challenge_id, solved_at, awarded_points)
VALUES ($1, $2, $3)
ON CONFLICT (team_challenge_id) DO UPDATE
SET solved_at = EXCLUDED.solved_at,
    awarded_points = COALESCE(team_challenge_solves.awarded_points, EXCLUDED.awarded_points)
`

type UpsertTeamChallengeSolveParams struct {
	TeamChallengeID uuid.UUID   `json:"team_challenge_id"`
	SolvedAt        time.Time   `json:"solved_at"`
	AwardedPoints   pgtype.Int4 `json:"awarded_points"`
}

func (q *Queries) UpsertTeamChallengeSolve(ctx context.Context, arg UpsertTeamChallengeSolveParams) error {
	_, err := q.db.Exec(ctx, upsertTeamChallengeSolve, arg.TeamChallengeID, arg.SolvedAt, arg.AwardedPoints)
	return err
}
